from pathlib import Path
import sys


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return text.replace(old, new, 1)


def main(path: str) -> None:
    p = Path(path)
    s = p.read_text(encoding="utf-8-sig")

    s = replace_once(s, 'APP_VERSION = "1.11.18"', 'APP_VERSION = "1.11.19"', 'version')

    s = replace_once(
        s,
        '''APP_NAME = "Pastel Payment Assistant"\nAPP_VERSION = "1.11.19"\n\n\ndef app_data_dir() -> Path:\n    base = os.environ.get("APPDATA") if os.name == "nt" else None\n    root = Path(base) if base else Path.home() / ".pastel_payment_assistant"\n    p = root / "PastelPaymentAssistant" if base else root\n    p.mkdir(parents=True, exist_ok=True)\n    return p\n''',
        '''APP_NAME = "Pastel Payment Assistant"\nAPP_VERSION = "1.11.19"\nAPP_DATA_NAMESPACE = "PastelPaymentAssistant"\nAPP_DATA_FALLBACK = ".pastel_payment_assistant"\nSESSION_SETTING_KEY = "__autosaved_session_v1"\nBUNDLED_RULES_FILENAME = "Pastel_Payment_Receipt_Rules_Backup.csv"\nALLOW_BUNDLED_RULE_BOOTSTRAP = True\n\n\ndef app_data_dir() -> Path:\n    base = os.environ.get("APPDATA") if os.name == "nt" else None\n    root = Path(base) if base else Path.home()\n    p = root / APP_DATA_NAMESPACE if base else root / APP_DATA_FALLBACK\n    p.mkdir(parents=True, exist_ok=True)\n    return p\n''',
        'app data namespace constants',
    )

    session_helpers = '''\n\ndef transaction_to_session_dict(t: "Transaction") -> Dict[str, object]:\n    """Serialize every user-editable transaction field needed to resume a session."""\n    return {\n        "row_no": int(t.row_no),\n        "txn_date": t.txn_date.isoformat(),\n        "amount": str(t.amount),\n        "txn_type": t.txn_type,\n        "details": t.details,\n        "bank_code": t.bank_code,\n        "source": t.source,\n        "include": bool(t.include),\n        "rule_id": t.rule_id,\n        "rule_name": t.rule_name,\n        "account": t.account,\n        "vat": bool(t.vat),\n        "tax_type": int(t.tax_type or 0),\n        "match_key": t.match_key,\n        "pastel_ref": t.pastel_ref,\n        "status": t.status,\n        "manual_override": bool(t.manual_override),\n        "ambiguous": bool(t.ambiguous),\n        "recurring_count": int(t.recurring_count or 1),\n        "previously_seen": bool(t.previously_seen),\n        "direction": (t.direction or "PAYMENT").upper(),\n        "contra": t.contra,\n        "description": t.description,\n        "auto_allocated": bool(t.auto_allocated),\n        "amount_condition_applied": bool(t.amount_condition_applied),\n    }\n\n\ndef transaction_from_session_dict(data: Dict[str, object]) -> "Transaction":\n    """Recreate a Transaction from an autosaved session snapshot."""\n    raw_date = str(data.get("txn_date") or "")\n    try:\n        txn_date = date.fromisoformat(raw_date)\n    except ValueError:\n        txn_date = date.today()\n    rid = data.get("rule_id")\n    try:\n        rule_id = int(rid) if rid not in (None, "") else None\n    except (TypeError, ValueError):\n        rule_id = None\n    return Transaction(\n        row_no=int(data.get("row_no") or 0),\n        txn_date=txn_date,\n        amount=D(data.get("amount") or "0"),\n        txn_type=str(data.get("txn_type") or ""),\n        details=str(data.get("details") or ""),\n        bank_code=str(data.get("bank_code") or ""),\n        source=str(data.get("source") or ""),\n        include=bool(data.get("include", True)),\n        rule_id=rule_id,\n        rule_name=str(data.get("rule_name") or ""),\n        account=str(data.get("account") or ""),\n        vat=bool(data.get("vat", False)),\n        tax_type=int(data.get("tax_type") or 0),\n        match_key=str(data.get("match_key") or ""),\n        pastel_ref=str(data.get("pastel_ref") or ""),\n        status=str(data.get("status") or "Unassigned"),\n        manual_override=bool(data.get("manual_override", False)),\n        ambiguous=bool(data.get("ambiguous", False)),\n        recurring_count=int(data.get("recurring_count") or 1),\n        previously_seen=bool(data.get("previously_seen", False)),\n        direction=str(data.get("direction") or "PAYMENT").upper(),\n        contra=str(data.get("contra") or ""),\n        description=str(data.get("description") or ""),\n        auto_allocated=bool(data.get("auto_allocated", False)),\n        amount_condition_applied=bool(data.get("amount_condition_applied", False)),\n    )\n'''
    s = replace_once(s, '\n\nclass Store:\n', session_helpers + '\n\nclass Store:\n', 'transaction session helpers')

    s = replace_once(
        s,
        '''        self._build()\n        self._refresh_profile_ui()\n        self.protocol("WM_DELETE_WINDOW", self.on_close)\n''',
        '''        self._build()\n        self._refresh_profile_ui()\n        self._startup_restore()\n        self.protocol("WM_DELETE_WINDOW", self.on_close)\n''',
        'startup session restore',
    )

    app_methods = '''    def _app_folder(self) -> Path:\n        if getattr(sys, "frozen", False):\n            return Path(sys.executable).resolve().parent\n        return Path(__file__).resolve().parent\n\n    def _bootstrap_rules_if_present(self) -> int:\n        """Import a rules backup beside the EXE only into a completely empty profile.\n\n        The public portable build does not contain a rules file. This hook allows a\n        private/personal bundle to carry the user's rules without hard-coding or\n        publishing them. Existing profiles are never overwritten or duplicated.\n        """\n        if not ALLOW_BUNDLED_RULE_BOOTSTRAP:\n            return 0\n        try:\n            if self.store.all_rules():\n                return 0\n        except Exception:\n            return 0\n        candidate = self._app_folder() / BUNDLED_RULES_FILENAME\n        if not candidate.exists():\n            return 0\n        count = 0\n        try:\n            with open(candidate, newline="", encoding="utf-8-sig") as f:\n                for row in csv.DictReader(f):\n                    direction = (row.get("direction") or "PAYMENT").strip().upper()\n                    if direction not in self.DIRECTIONS:\n                        direction = "PAYMENT"\n                    try:\n                        tax_type = int(row.get("tax_type", "0") or 0)\n                    except ValueError:\n                        tax_type = 0\n                    try:\n                        priority = int(row.get("priority", "100") or 100)\n                    except ValueError:\n                        priority = 100\n                    r = Rule(\n                        id=None,\n                        name=(row.get("name") or "").strip(),\n                        mode=(row.get("mode") or "SMART").strip(),\n                        pattern=(row.get("pattern") or "").strip(),\n                        account=(row.get("account") or "").strip(),\n                        vat=(row.get("vat") or "0").strip() in {"1", "true", "True", "yes", "Yes"},\n                        tax_type=tax_type,\n                        pastel_ref=(row.get("pastel_ref") or "").strip(),\n                        priority=priority,\n                        enabled=(row.get("enabled") or "1").strip() not in {"0", "false", "False"},\n                        direction=direction,\n                        description=(row.get("description") or "").strip(),\n                        amount_operator=(row.get("amount_operator") or "").strip(),\n                        amount_threshold=(row.get("amount_threshold") or "").strip(),\n                        amount_account=(row.get("amount_account") or "").strip(),\n                        amount_description=(row.get("amount_description") or "").strip(),\n                        amount_action=((row.get("amount_action") or "AUTO").strip().upper() or "AUTO"),\n                    )\n                    if r.name and r.pattern and r.account:\n                        self.store.save_rule(r)\n                        count += 1\n        except Exception as e:\n            self.status_var.set(f"Bundled rules were not imported: {e}")\n            return 0\n        if count:\n            self.refresh_rules()\n        return count\n\n    def _session_ui_snapshot(self) -> Dict[str, object]:\n        tx_selection = {}\n        recurring_selection = {}\n        recurring_open = {}\n        for direction in self.DIRECTIONS:\n            tree = self.trees.get(direction)\n            tx_selection[direction] = list(tree.selection()) if tree else []\n            rtree = self.recurring_trees.get(direction)\n            recurring_selection[direction] = list(rtree.selection()) if rtree else []\n            opened = []\n            if rtree:\n                for pid in rtree.get_children(""):\n                    if rtree.item(pid, "open"):\n                        opened.append(pid)\n                    for kid in rtree.get_children(pid):\n                        if rtree.item(kid, "open"):\n                            opened.append(kid)\n            recurring_open[direction] = opened\n        active_tab = ""\n        try:\n            selected_tab = self.notebook.select()\n            active_tab = str(self.notebook.tab(selected_tab, "text")) if selected_tab else ""\n        except Exception:\n            pass\n        return {\n            "search": {d: self.search_vars[d].get() for d in self.DIRECTIONS},\n            "filter": {d: self.filter_vars[d].get() for d in self.DIRECTIONS},\n            "repeat": {d: self.repeat_vars[d].get() for d in self.DIRECTIONS},\n            "sort": {d: self.sort_vars[d].get() for d in self.DIRECTIONS},\n            "transaction_selection": tx_selection,\n            "recurring_selection": recurring_selection,\n            "recurring_open": recurring_open,\n            "active_tab": active_tab,\n            "window_geometry": self.geometry(),\n        }\n\n    def _save_session(self) -> bool:\n        """Persist the current statement and UI state inside the active profile DB."""\n        try:\n            ui = self._session_ui_snapshot()\n            payload = {\n                "schema": 1,\n                "saved_at": datetime.now().isoformat(timespec="seconds"),\n                "current_file": self.current_file,\n                "parser_name": self.parser_name,\n                "payments": [transaction_to_session_dict(t) for t in self.txns],\n                "receipts": [transaction_to_session_dict(t) for t in self.receipts],\n                **ui,\n            }\n            self.store.set_setting(SESSION_SETTING_KEY, json.dumps(payload, ensure_ascii=False, separators=(",", ":")))\n            return True\n        except Exception as e:\n            try:\n                self.status_var.set(f"Could not autosave current session: {e}")\n            except Exception:\n                pass\n            return False\n\n    def _restore_session(self) -> bool:\n        """Restore the last autosaved snapshot for the active company profile."""\n        try:\n            raw = self.store.get_setting(SESSION_SETTING_KEY, "")\n        except Exception:\n            return False\n        if not raw:\n            return False\n        try:\n            data = json.loads(raw)\n            if not isinstance(data, dict) or int(data.get("schema") or 0) != 1:\n                return False\n            self.txns = [transaction_from_session_dict(x) for x in (data.get("payments") or []) if isinstance(x, dict)]\n            self.receipts = [transaction_from_session_dict(x) for x in (data.get("receipts") or []) if isinstance(x, dict)]\n            self.current_file = str(data.get("current_file") or "")\n            self.parser_name = str(data.get("parser_name") or "")\n\n            saved_search = data.get("search") if isinstance(data.get("search"), dict) else {}\n            saved_filter = data.get("filter") if isinstance(data.get("filter"), dict) else {}\n            saved_repeat = data.get("repeat") if isinstance(data.get("repeat"), dict) else {}\n            saved_sort = data.get("sort") if isinstance(data.get("sort"), dict) else {}\n            for direction in self.DIRECTIONS:\n                self.search_vars[direction].set(str(saved_search.get(direction, "")))\n                self.filter_vars[direction].set(str(saved_filter.get(direction, "All")))\n                self.sort_vars[direction].set(str(saved_sort.get(direction, "Oldest first")))\n                self.update_repeat_dropdown(direction)\n                self.repeat_vars[direction].set(str(saved_repeat.get(direction, "— Select repeat description —")))\n                self.refresh_transaction_tree(direction)\n                self.refresh_recurring_tree(direction)\n            self.refresh_rules()\n\n            saved_open = data.get("recurring_open") if isinstance(data.get("recurring_open"), dict) else {}\n            saved_rsel = data.get("recurring_selection") if isinstance(data.get("recurring_selection"), dict) else {}\n            saved_tsel = data.get("transaction_selection") if isinstance(data.get("transaction_selection"), dict) else {}\n            for direction in self.DIRECTIONS:\n                tree = self.trees.get(direction)\n                if tree:\n                    valid = [str(iid) for iid in (saved_tsel.get(direction) or []) if tree.exists(str(iid))]\n                    if valid:\n                        tree.selection_set(valid)\n                        tree.see(valid[0])\n                rtree = self.recurring_trees.get(direction)\n                if rtree:\n                    for iid in (saved_open.get(direction) or []):\n                        iid = str(iid)\n                        if rtree.exists(iid):\n                            rtree.item(iid, open=True)\n                    valid_r = [str(iid) for iid in (saved_rsel.get(direction) or []) if rtree.exists(str(iid))]\n                    if valid_r:\n                        rtree.selection_set(valid_r)\n                        rtree.see(valid_r[0])\n\n            active_tab = str(data.get("active_tab") or "")\n            if active_tab:\n                for tab_id in self.notebook.tabs():\n                    if str(self.notebook.tab(tab_id, "text")) == active_tab:\n                        self.notebook.select(tab_id)\n                        break\n            geometry = str(data.get("window_geometry") or "")\n            if geometry and "x" in geometry:\n                try:\n                    self.geometry(geometry)\n                except Exception:\n                    pass\n\n            if self.txns or self.receipts:\n                source_note = ""\n                if self.current_file and not Path(self.current_file).exists():\n                    source_note = " The original CSV is no longer at its saved path; the autosaved transaction snapshot was restored instead."\n                saved_at = str(data.get("saved_at") or "previous exit")\n                self.status_var.set(f"Restored autosaved session from {saved_at}.{source_note}")\n                return True\n            return False\n        except Exception as e:\n            self.status_var.set(f"Saved session could not be restored: {e}")\n            return False\n\n    def _startup_restore(self):\n        imported = self._bootstrap_rules_if_present()\n        restored = self._restore_session()\n        if imported and not restored:\n            self.status_var.set(f"Imported {imported} bundled saved rule(s) into this empty profile. Load a bank CSV to continue.")\n\n    def _confirm_profile_change(self) -> bool:\n        if not (self.txns or self.receipts):\n            return True\n        return messagebox.askyesno(\n            APP_NAME,\n            "Switch company profiles?\\n\\nThe current statement, allocations, export ticks and view state will be autosaved to this profile and restored when you return."\n        )\n\n    def _activate_profile(self, profile_id: str):\n        if profile_id == self.active_profile_id:\n            self._refresh_profile_ui()\n            return\n        self._save_session()\n        self._persist_profile_settings()\n        try:\n            self.store.conn.close()\n        except Exception:\n            pass\n        self.profile_manager.set_active(profile_id)\n        self.active_profile_id = profile_id\n        self.store = Store(self.profile_manager.db_path(profile_id))\n        self._load_active_profile_settings()\n        self._clear_statement_for_profile_change()\n        self._refresh_profile_ui()\n        imported = self._bootstrap_rules_if_present()\n        restored = self._restore_session()\n        name = self.profile_manager.profile_name(profile_id)\n        if restored:\n            self.status_var.set(f"Switched to profile '{name}' and restored its autosaved session.")\n        elif imported:\n            self.status_var.set(f"Switched to profile '{name}'. Imported {imported} bundled rule(s); no prior statement session was saved.")\n        else:\n            self.status_var.set(f"Switched to profile '{name}'. No prior statement session was saved.")\n\n    def delete_profile(self):\n        if self.active_profile_id == "default":\n            messagebox.showinfo(APP_NAME, "The Default profile contains the original app database and cannot be deleted. You can rename it to the company name instead.")\n            return\n        name = self.profile_manager.profile_name(self.active_profile_id)\n        if not messagebox.askyesno(APP_NAME, f"Delete profile '{name}'?\\n\\nThis permanently deletes that profile's saved rules, settings, transaction history and autosaved session. This cannot be undone."):\n            return\n        self._persist_profile_settings()\n        try:\n            self.store.conn.close()\n        except Exception:\n            pass\n        old_id = self.active_profile_id\n        self.profile_manager.delete_profile(old_id)\n        self.active_profile_id = self.profile_manager.active_id\n        self.store = Store(self.profile_manager.db_path(self.active_profile_id))\n        self._load_active_profile_settings()\n        self._clear_statement_for_profile_change()\n        self._refresh_profile_ui()\n        self._bootstrap_rules_if_present()\n        restored = self._restore_session()\n        target = self.profile_manager.profile_name(self.active_profile_id)\n        self.status_var.set(f"Deleted profile '{name}'. Switched to '{target}'" + (" and restored its autosaved session." if restored else "."))\n\n'''
    s = replace_once(s, '    def _configure_style(self):\n', app_methods + '    def _configure_style(self):\n', 'profile-scoped autosave app methods')

    later_on_close = '''    def on_close(self):\n        """Autosave the complete active-profile session before the window closes."""\n        try:\n            self._save_session()\n            self._persist_profile_settings()\n            self.store.conn.close()\n        except Exception:\n            pass\n        self.destroy()\n\n'''
    s = replace_once(
        s,
        '\ndef self_test(statement_path: Optional[str] = None) -> str:\n',
        '\n' + later_on_close + 'def self_test(statement_path: Optional[str] = None) -> str:\n',
        'final autosaving on_close override',
    )

    test_marker = '    # Receipt and payment rules with the same description must never cross-apply.\n'
    tests = '''    # v1.11.19: autosaved transaction snapshots preserve manual/auto/export state.\n    session_probe = Transaction(1119, date(2026, 8, 22), Decimal("123.45"), "RECEIPT", "SESSION TEST", direction="RECEIPT")\n    session_probe.include = False\n    session_probe.rule_id = 77\n    session_probe.rule_name = "Saved rule"\n    session_probe.account = "9800000"\n    session_probe.description = "RESTORED DESC"\n    session_probe.vat = True\n    session_probe.tax_type = 15\n    session_probe.match_key = "SESSION TEST"\n    session_probe.pastel_ref = "R8-0001"\n    session_probe.status = "Corrected allocation • this statement only"\n    session_probe.manual_override = True\n    session_probe.recurring_count = 3\n    session_probe.previously_seen = True\n    session_probe.auto_allocated = False\n    restored_probe = transaction_from_session_dict(transaction_to_session_dict(session_probe))\n    assert restored_probe.txn_date == session_probe.txn_date and restored_probe.amount == session_probe.amount\n    assert restored_probe.direction == "RECEIPT" and not restored_probe.include\n    assert restored_probe.account == "9800000" and restored_probe.description == "RESTORED DESC"\n    assert restored_probe.vat and restored_probe.tax_type == 15 and restored_probe.manual_override\n    assert restored_probe.status == session_probe.status and restored_probe.recurring_count == 3 and restored_probe.previously_seen\n\n'''
    s = replace_once(s, test_marker, tests + test_marker, 'autosave transaction snapshot self-test')

    p.write_text(s, encoding="utf-8")
    print(f"Transformed {p} to v1.11.19 with profile-scoped autosave/resume and optional private rule bootstrap")


if __name__ == "__main__":
    main(sys.argv[1])
